510	import type { AppRouter } from '@repo/api';
511	import { TRPCClientError, type TRPCLink } from '@trpc/client';
512	import { observable } from '@trpc/server/observable';
513	import type { RouterInputs, RouterOutputs } from './trpc';
514	
515	type ProcedurePath = {
516	  [Router in keyof RouterInputs & string]: `${Router}.${keyof RouterInputs[Router] & string}`;
517	}[keyof RouterInputs & string];
518	
519	type Lookup<Tree, Path> = Path extends `${infer Router}.${infer Procedure}`
520	  ? Router extends keyof Tree
521	    ? Procedure extends keyof Tree[Router]
522	      ? Tree[Router][Procedure]
523	      : never
524	    : never
525	  : never;
526	
527	/** A fake answer per procedure path, such as `'greeting.greet'`, typed by the router. */
528	export type TestApiHandlers = {
529	  readonly [Path in ProcedurePath]?: (
530	    input: Lookup<RouterInputs, Path>,
531	  ) => Lookup<RouterOutputs, Path> | Promise<Lookup<RouterOutputs, Path>>;
532	};
533	
534	/** A tRPC link that answers each call from `handlers` instead of the network. */
535	export function handlerLink(handlers: TestApiHandlers): TRPCLink<AppRouter> {
536	  return () =>
537	    ({ op }) =>
538	      observable((observer) => {
539	        const handler = handlers[op.path as ProcedurePath] as
540	          | ((input: unknown) => unknown)
541	          | undefined;
542	        Promise.resolve(op.input)
543	          .then((input) => {
544	            if (!handler) {
545	              throw new Error(`TestApiProvider has no handler for ${op.path}`);
546	            }
547	            return handler(input);
548	          })
549	          .then(
550	            (data) => {
551	              observer.next({ result: { type: 'data', data } });
552	              observer.complete();
553	            },
554	            (cause: Error) => observer.error(TRPCClientError.from(cause)),
555	          );
556	      });
557	}
