916	import { skipToken, useQuery } from '@tanstack/react-query';
917	import { useState } from 'react';
918	import { type RouterInputs, type RouterOutputs, useTrpc } from '../../api-client';
919	
920	type GreetInput = RouterInputs['greeting']['greet'];
921	type Greeting = RouterOutputs['greeting']['greet'];
922	
923	export type GreetingState =
924	  | { readonly status: 'idle' }
925	  | { readonly status: 'loading' }
926	  | { readonly status: 'success'; readonly message: Greeting['message'] }
927	  | { readonly status: 'error' };
928	
929	/** The greeting for the last submitted name, fetched through the api. */
930	export function useGreeting() {
931	  const [name, setName] = useState<GreetInput['name'] | null>(null);
932	  const trpc = useTrpc();
933	  const query = useQuery(trpc.greeting.greet.queryOptions(name === null ? skipToken : { name }));
934	
935	  function requestGreeting(nextName: GreetInput['name']) {
936	    setName(nextName);
937	    if (nextName === name) {
938	      void query.refetch();
939	    }
940	  }
941	
942	  let greeting: GreetingState;
943	  if (name === null) {
944	    greeting = { status: 'idle' };
945	  } else if (query.isFetching) {
946	    greeting = { status: 'loading' };
947	  } else if (query.isError) {
948	    greeting = { status: 'error' };
949	  } else if (query.data) {
950	    greeting = { status: 'success', message: query.data.message };
951	  } else {
952	    greeting = { status: 'loading' };
953	  }
954	  return { greeting, requestGreeting };
955	}
