cat > features/todos/domain.ts <<'EOF'
export interface Todo {
  readonly id: string;
  readonly title: string;
  readonly completed: boolean;
}

/** A new todo starts not complete. */
export function newTodo(id: string, title: string): Todo {
  return { id, title, completed: false };
}

export function toggled(todo: Todo): Todo {
  return { ...todo, completed: !todo.completed };
}
EOF
cat > features/todos/integrations.ts <<'EOF'
import type { Todo } from './domain.ts';

/** The todos, kept in memory for the life of the api process, in creation order. */
const todos = new Map<string, Todo>();
let lastId = 0;

export function nextTodoId(): string {
  lastId += 1;
  return String(lastId);
}

export function readTodos(): readonly Todo[] {
  return [...todos.values()];
}

export function readTodo(id: string): Todo | undefined {
  return todos.get(id);
}

export function writeTodo(todo: Todo): void {
  todos.set(todo.id, todo);
}

/** True when a todo with this id was there to remove. */
export function removeTodo(id: string): boolean {
  return todos.delete(id);
}
EOF
cat > features/todos/application.ts <<'EOF'
import { newTodo, type Todo, toggled } from './domain.ts';
import { nextTodoId, readTodo, readTodos, removeTodo, writeTodo } from './integrations.ts';

export interface CreateTodoRequest {
  readonly title: string;
}

export interface TodoRequest {
  readonly id: string;
}

/** A use case on a todo id that names no todo. */
export class TodoNotFoundError extends Error {
  constructor(id: string) {
    super(`No todo has the id ${id}`);
    this.name = 'TodoNotFoundError';
  }
}

export function listTodos(): readonly Todo[] {
  return readTodos();
}

export function createTodo(request: CreateTodoRequest): Todo {
  const todo = newTodo(nextTodoId(), request.title);
  writeTodo(todo);
  return todo;
}

export function toggleTodo(request: TodoRequest): Todo {
  const todo = readTodo(request.id);
  if (!todo) {
    throw new TodoNotFoundError(request.id);
  }
  const next = toggled(todo);
  writeTodo(next);
  return next;
}

export function deleteTodo(request: TodoRequest): TodoRequest {
  if (!removeTodo(request.id)) {
    throw new TodoNotFoundError(request.id);
  }
  return { id: request.id };
}
EOF
cat > features/todos/procedures.ts <<'EOF'
import { TRPCError } from '@trpc/server';
import { Schema } from 'effect';
import { procedure, router } from '../../trpc.ts';
import {
  createTodo,
  deleteTodo,
  listTodos,
  TodoNotFoundError,
  toggleTodo,
} from './application.ts';

const createTodoInputSchema = Schema.Struct({ title: Schema.Trim.pipe(Schema.nonEmptyString()) });
const todoIdInputSchema = Schema.Struct({ id: Schema.NonEmptyString });

/** Runs a use case and answers a missing todo as NOT_FOUND. */
function mapNotFound<Output>(useCase: () => Output): Output {
  try {
    return useCase();
  } catch (error) {
    if (error instanceof TodoNotFoundError) {
      throw new TRPCError({ code: 'NOT_FOUND', message: error.message, cause: error });
    }
    throw error;
  }
}

export const todosRouter = router({
  list: procedure.query(() => listTodos()),
  create: procedure
    .input(Schema.standardSchemaV1(createTodoInputSchema))
    .mutation(({ input }) => createTodo(input)),
  toggle: procedure
    .input(Schema.standardSchemaV1(todoIdInputSchema))
    .mutation(({ input }) => mapNotFound(() => toggleTodo(input))),
  delete: procedure
    .input(Schema.standardSchemaV1(todoIdInputSchema))
    .mutation(({ input }) => mapNotFound(() => deleteTodo(input))),
});
EOF
